    "exercises": [
      {"q": "Quina és la frase correcta?", "o": ["Han encarregat una anàlisi exhaustiva de l'aigua.", "Han encarregat un anàlisi exhaustiu de l'aigua.", "Han encarregat un anàlisi exhaustiva de l'aigua."], "e": "Anàlisi és femení en valencià (una anàlisi), al contrari del castellà (el análisis). GNV 10.3.2."},
      {"q": "Quina és la frase correcta?", "o": ["Al migdia feia una calor sufocant.", "Al migdia feia un calor sufocant.", "Al migdia feia un calor sufocant i pesat."], "e": "Calor és femení: la calor, una calor sufocant (en castellà, el calor). GNV 10.3.2."},
      {"q": "Quina és la frase correcta?", "o": ["Tinc un dubte raonable sobre l'oferta.", "Tinc una dubte raonable sobre l'oferta.", "Tinc una duda raonable sobre l'oferta."], "e": "Dubte és masculí: el dubte (en castellà, la duda). GNV 10.3.2."},
      {"q": "Quina és la frase correcta?", "o": ["Per la finestra entrava un corrent d'aire fred.", "Per la finestra entrava una corrent d'aire fred.", "Per la finestra entrava una corrent d'aire freda."], "e": "Corrent com a nom és masculí: un corrent d'aire, un corrent d'opinió (en castellà, la corriente). DNV."},
      {"q": "Escriu l'article indefinit que falta: «Em va arribar ___ olor de pa calent.»", "a": ["una", "una olor"], "e": "Olor és femení: una olor (en castellà, el olor). GNV 10.3.2."},
      {"q": "Quina és la frase correcta?", "o": ["De matinada només se sentia la remor de la mar.", "De matinada només se sentia el remor de la mar.", "De matinada només se sentia el rumor de la mar."], "e": "Remor és femení: la remor (en castellà, el rumor). GNV 10.3.2."},
      {"q": "Quina és la frase correcta?", "o": ["Tenia la suor freda després de la prova.", "Tenia el suor fred després de la prova.", "Tenia el sudor fred després de la prova."], "e": "Suor és femení: la suor (en castellà, el sudor). GNV 10.3.2."},
      {"q": "Escriu l'article indefinit que falta: «Van córrer ___ marató benèfica pels carrers de la ciutat.»", "a": ["una"], "e": "Marató és femení: una marató (en castellà, el maratón). GNV 10.3.2."},
      {"q": "Quina és la frase correcta?", "o": ["Diagnosticaren la síndrome de fatiga crònica.", "Diagnosticaren el síndrome de fatiga crònica.", "Diagnosticaren el sindrome de fatiga crònica."], "e": "Síndrome és femení: la síndrome (en castellà, el síndrome). GNV 10.3.2."},
      {"q": "Quin és el gènere de «avantatge» en valencià?", "o": ["Masculí: un avantatge", "Femení: una avantatge", "Els dos indistintament"], "e": "Avantatge és masculí (en castellà, la ventaja). GNV 10.3.2."},
      {"q": "Quina és la frase correcta?", "o": ["Ha pagat per fi tot el deute pendent.", "Ha pagat per fi tota la deute pendent.", "Ha pagat per fi tota la deuta pendent."], "e": "Deute és masculí: el deute (en castellà, la deuda). GNV 10.3.2."},
      {"q": "Escriu l'article indefinit que falta: «Al teatre hi havia ___ titella de fil que feia riure els xiquets.»", "a": ["un"], "e": "Titella és masculí: un titella (en castellà, el títere). GNV 10.3.2."},
